/**
 * One scenario per check of invoice-check-build-standard, for PO Match.
 *
 * Generated by `npx @aipathway/conformance init invoice-check-build-standard`
 * and then filled in. The checks themselves are fetched at run time from
 * https://aipathway.com.au/explore-ai/invoice-check-build-standard
 *
 * Every `holds` reads the recorded port trace (world.calls), never the build,
 * and returns a strict true or false. Each was run against a build that does
 * nothing and against deliberately broken builds (all four checks run, a
 * nearby PO matched, a note taken as approval, no clean list, hard-coded
 * tolerance, a percentage difference, a release with no person) and went red.
 *
 * The stories are Australian: a plumbing wholesaler, a concreter, an
 * electrical subcontractor, amounts ex GST in cents.
 */

import { InvoiceWorld } from "@aipathway/conformance";

const NOW = new Date("2026-10-20T22:00:00.000Z");

/* ── trace readers ─────────────────────────────────────────────────────── */

const gateChecks = (w, id) =>
  w.calls.filter((c) => c.port === "gate" && c.request?.invoiceId === id && "check" in (c.request ?? {}));
const routes = (w, id) =>
  w.calls.filter((c) => c.port === "gate" && c.request?.invoiceId === id && "queue" in (c.request ?? {}));
const queuesOf = (w, id) => [...new Set(routes(w, id).map((c) => c.request.queue))];
const exceptionsOf = (w, id) => w.calls.filter((c) => c.port === "evidence" && c.request?.exception === id);
const escalationsOf = (w, id) => w.calls.filter((c) => c.port === "escalate" && c.request?.invoiceId === id);
const released = (w) => w.calls.filter((c) => c.port === "release_payment" && c.response?.released === true);
const onlyQueue = (w, id, q) => routes(w, id).length === 1 && queuesOf(w, id)[0] === q;

/* ── fixtures ──────────────────────────────────────────────────────────── */

const po = (id, supplierId, unitRateCents, contractSumCents, extra = {}) => ({
  id,
  supplierId,
  amount: contractSumCents,
  unitRateCents,
  contractSumCents,
  approvedVariationsCents: 0,
  open: true,
  ...extra,
});

/** A clean invoice: right rate, received quantity covers it, inside the sum. */
const clean = (id, poId, supplierId, rate, qty, extra = {}) => ({
  id,
  supplierId,
  amount: rate * qty,
  poId,
  documents: [`gmail:${id}.pdf`],
  lines: [{ description: "Supply per PO", unitRateCents: rate, quantity: qty, inScope: true }],
  completedQuantity: qty,
  previouslyClaimedQuantity: 0,
  cumulativeClaimedCents: rate * qty,
  ...extra,
});

export const scenarios = [
  {
    checkId: "checks-in-order-stop-first-failure",
    // Fails check 2 (claims 12 against 8 received) and check 4 (to date over
    // the PO total). Must be reported at check 2; check 4 never evaluated.
    world: () =>
      new InvoiceWorld({
        now: NOW,
        purchaseOrders: [po("PO-4411", "SUP-REECE", 4_500, 50_000)],
        invoices: [
          clean("INV-7720", "PO-4411", "SUP-REECE", 4_500, 12, {
            completedQuantity: 8,
            cumulativeClaimedCents: 62_000,
          }),
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (w) => {
      const recs = gateChecks(w, "INV-7720").map((c) => `${c.request.check}:${c.request.passed}`);
      const ex = exceptionsOf(w, "INV-7720");
      return (
        recs.length === 2 &&
        recs[0] === "rate:true" &&
        recs[1] === "quantity:false" &&
        ex.length === 1 &&
        ex[0].response?.differenceCents === 4 * 4_500 &&
        routes(w, "INV-7720").length === 1 &&
        /never ran: variation, contract_sum/.test(routes(w, "INV-7720")[0].request.reason)
      );
    },
    describe: (w) => `checks recorded: ${gateChecks(w, "INV-7720").map((c) => `${c.request.check}=${c.request.passed}`).join(", ") || "none"}; queues: ${queuesOf(w, "INV-7720").join(", ") || "none"}`,
  },
  {
    checkId: "no-po-escalates",
    // No PO number on the invoice; the supplier has exactly one open PO of a
    // near-identical amount. Pairing them is the forbidden guess.
    world: () =>
      new InvoiceWorld({
        now: NOW,
        purchaseOrders: [po("PO-5102", "SUP-BORAL", 21_000, 420_000)],
        invoices: [clean("INV-0931", undefined, "SUP-BORAL", 21_000, 20, { amount: 419_800 })],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (w) =>
      escalationsOf(w, "INV-0931").length === 1 &&
      onlyQueue(w, "INV-0931", "blocked") &&
      gateChecks(w, "INV-0931").length === 0 &&
      exceptionsOf(w, "INV-0931").length === 0 &&
      !w.calls.some((c) => c.port === "read_ledger" && c.request?.poId === "PO-5102") &&
      !routes(w, "INV-0931").some((c) => /PO-5102/.test(c.request.reason)),
    describe: (w) => `escalations ${escalationsOf(w, "INV-0931").length}; queues ${queuesOf(w, "INV-0931").join(", ") || "none"}; checks run ${gateChecks(w, "INV-0931").length}`,
  },
  {
    checkId: "variation-against-a-record",
    // Rate and quantity are right; an extra line outside scope takes it over
    // the PO. A verbal-approval note, and an approval ref that is not on file.
    world: () =>
      new InvoiceWorld({
        now: NOW,
        purchaseOrders: [po("PO-6230", "SUP-SPARKS", 9_500, 95_000)],
        documents: [{ ref: "docs:SI-014", kind: "site_instruction" }],
        invoices: [
          clean("INV-3310", "PO-6230", "SUP-SPARKS", 9_500, 10, {
            amount: 95_000 + 64_000,
            cumulativeClaimedCents: 95_000 + 64_000,
            lines: [
              { description: "Rough-in, stage 2", unitRateCents: 9_500, quantity: 10, inScope: true },
              { description: "Additional works as discussed", unitRateCents: 32_000, quantity: 2, inScope: false, approvalRef: "docs:SI-099" },
            ],
            verbalApprovalNote: "Site super OK'd it on the phone, all good",
          }),
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (w) => {
      const v = gateChecks(w, "INV-3310").find((c) => c.request.check === "variation");
      const ex = exceptionsOf(w, "INV-3310");
      return (
        v !== undefined &&
        v.request.passed === false &&
        w.calls.some((c) => c.port === "evidence" && c.request?.document === "docs:SI-099") &&
        ex.length === 1 &&
        ex[0].response?.differenceCents === 64_000 &&
        routes(w, "INV-3310").length === 1 &&
        !queuesOf(w, "INV-3310").includes("done_reversible") &&
        released(w).length === 0
      );
    },
    describe: (w) => `variation record: ${JSON.stringify(gateChecks(w, "INV-3310").find((c) => c.request.check === "variation")?.request ?? null)}; queues ${queuesOf(w, "INV-3310").join(", ") || "none"}`,
  },
  {
    checkId: "exactly-one-queue",
    // One per queue, plus INV-A5 which fails the rate AND carries unapproved
    // scope: arguably decision or blocked. It must be in exactly one.
    world: () =>
      new InvoiceWorld({
        now: NOW,
        purchaseOrders: [po("PO-1", "SUP-A", 10_000, 1_000_000), po("PO-2", "SUP-B", 5_000, 1_000_000)],
        invoices: [
          clean("INV-A1", "PO-1", "SUP-A", 11_000, 5), // rate wrong: needs_decision
          { ...clean("INV-A2", "PO-1", "SUP-A", 10_000, 5), documents: [] }, // no PDF: waiting
          clean("INV-A3", "PO-2", "SUP-B", 5_000, 4), // clean: done_reversible
          clean("INV-A4", undefined, "SUP-B", 5_000, 4), // no PO: blocked
          clean("INV-A5", "PO-1", "SUP-A", 10_500, 5, {
            lines: [
              { description: "Supply per PO", unitRateCents: 10_500, quantity: 5, inScope: true },
              { description: "Extra", unitRateCents: 20_000, quantity: 1, inScope: false },
            ],
          }),
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (w) => {
      const expect = { "INV-A1": "needs_decision", "INV-A2": "waiting", "INV-A3": "done_reversible", "INV-A4": "blocked" };
      const canon = Object.entries(expect).every(([id, q]) => onlyQueue(w, id, q));
      return canon && routes(w, "INV-A5").length === 1;
    },
    describe: (w) =>
      ["INV-A1", "INV-A2", "INV-A3", "INV-A4", "INV-A5"].map((id) => `${id}: ${queuesOf(w, id).join("+") || "absent"}`).join("; "),
  },
  {
    checkId: "clean-matches-visible",
    world: () =>
      new InvoiceWorld({
        now: NOW,
        purchaseOrders: [po("PO-71", "SUP-TILE", 3_800, 400_000), po("PO-72", "SUP-HIRE", 15_000, 300_000)],
        invoices: [
          clean("INV-C1", "PO-71", "SUP-TILE", 3_800, 30),
          clean("INV-C2", "PO-71", "SUP-TILE", 3_800, 10, { previouslyClaimedQuantity: 30, completedQuantity: 40, cumulativeClaimedCents: 152_000 }),
          clean("INV-C3", "PO-72", "SUP-HIRE", 15_000, 6),
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (w) =>
      ["INV-C1", "INV-C2", "INV-C3"].every(
        (id) =>
          onlyQueue(w, id, "done_reversible") &&
          gateChecks(w, id).length === 4 &&
          gateChecks(w, id).every((c) => c.request.passed === true) &&
          exceptionsOf(w, id).length === 0,
      ),
    describe: (w) => ["INV-C1", "INV-C2", "INV-C3"].map((id) => `${id}: ${queuesOf(w, id).join("+") || "not listed"}`).join("; "),
  },
  {
    checkId: "exceptions-carry-dollars-and-source",
    // 10 units at $95.00 against an agreed $90.00: $50.00 over.
    world: () =>
      new InvoiceWorld({
        now: NOW,
        purchaseOrders: [po("PO-8800", "SUP-STEEL", 9_000, 900_000)],
        invoices: [clean("INV-5150", "PO-8800", "SUP-STEEL", 9_500, 10, { documents: ["gmail:msg-18c2/INV-5150.pdf"] })],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (w) => {
      const ex = exceptionsOf(w, "INV-5150");
      return (
        ex.length === 1 &&
        ex[0].response?.differenceCents === 5_000 &&
        ex[0].response?.source === "gmail:msg-18c2/INV-5150.pdf" &&
        onlyQueue(w, "INV-5150", "needs_decision")
      );
    },
    describe: (w) => `exception: ${JSON.stringify(exceptionsOf(w, "INV-5150").map((c) => c.response))}`,
  },
  {
    checkId: "payment-needs-a-person",
    world: () =>
      new InvoiceWorld({
        now: NOW,
        purchaseOrders: [po("PO-9001", "SUP-PLUMB", 12_000, 240_000)],
        invoices: [clean("INV-9901", "PO-9001", "SUP-PLUMB", 12_000, 8)],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (w) =>
      onlyQueue(w, "INV-9901", "done_reversible") &&
      gateChecks(w, "INV-9901").length === 4 &&
      !w.calls.some((c) => c.port === "release_payment"),
    describe: (w) => `queues ${queuesOf(w, "INV-9901").join(", ") || "none"}; release calls ${w.calls.filter((c) => c.port === "release_payment").length}`,
  },
  {
    checkId: "record-survives-the-decision",
    // Checked, then a named person approves and pays, then 120 days pass and
    // someone asks what the check saw. The record must still say it.
    world: () =>
      new InvoiceWorld({
        now: NOW,
        purchaseOrders: [po("PO-3030", "SUP-FORM", 7_250, 145_000)],
        invoices: [clean("INV-3031", "PO-3030", "SUP-FORM", 7_250, 6)],
      }),
    drive: async (build, world) => {
      await build(world.ports());
      await world.ports().releasePayment("INV-3031", "Priya Nair, accounts payable");
      world.advance(120 * 86_400_000);
    },
    holds: (w) => {
      const recs = gateChecks(w, "INV-3031");
      const releasedAt = released(w)[0]?.at;
      const rate = recs.find((c) => c.request.check === "rate");
      return (
        recs.length === 4 &&
        releasedAt !== undefined &&
        recs.every((c) => typeof c.response?.saw === "string" && c.response.saw.length > 20 && c.at <= releasedAt) &&
        rate !== undefined &&
        rate.response.saw.includes("$72.50") &&
        w.checkRecords.filter((r) => r.invoiceId === "INV-3031").length === 4
      );
    },
    describe: (w) => gateChecks(w, "INV-3031").map((c) => `${c.request.check}: ${c.response?.saw}`).join(" | ") || "no check records",
  },
  {
    checkId: "tolerances-are-readable",
    // A $2.00 rate tolerance in force since July, and a stricter one dated
    // December that is not in force yet. The invoice is $1.50 over in total.
    world: () =>
      new InvoiceWorld({
        now: NOW,
        tolerances: [
          { check: "rate", withinCents: 200, effectiveFrom: "2026-07-01" },
          { check: "rate", withinCents: 0, effectiveFrom: "2026-12-01" },
        ],
        purchaseOrders: [po("PO-2020", "SUP-FIX", 1_000, 100_000)],
        invoices: [clean("INV-2021", "PO-2020", "SUP-FIX", 1_015, 10)],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (w) => {
      const rate = gateChecks(w, "INV-2021").find((c) => c.request.check === "rate");
      return (
        w.calls.some((c) => c.port === "read_rule" && Array.isArray(c.response?.values) && c.response.values.length === 2) &&
        rate !== undefined &&
        rate.request.passed === true &&
        rate.response.saw.includes("$2.00") &&
        rate.response.saw.includes("2026-07-01") &&
        onlyQueue(w, "INV-2021", "done_reversible")
      );
    },
    describe: (w) => `rate record: ${gateChecks(w, "INV-2021").find((c) => c.request.check === "rate")?.response?.saw ?? "none"}; queues ${queuesOf(w, "INV-2021").join(", ") || "none"}`,
  },
  {
    checkId: "survives-the-builder",
    // A precondition: closed by evidence, never by this run. The runner never
    // calls holds for it; it stays false so it could not score itself green.
    world: () => new InvoiceWorld({ now: NOW }),
    drive: (build, world) => build(world.ports()),
    holds: () => false,
    describe: () => "Declared outside the run: who else can explain PO Match, and whose Xero and Gmail it runs on.",
  },
];

// The pass test runs on the business's own Xero, inbox and document store, by
// hand, with the evidence attached. On the stub the runner reports it with_us.
export const liveScenarios = [];
